-- Schilderbibliotheek — normen uit Calc4You en OnderhoudNL Basisverfbestek 2020
--
-- GEGENEREERD door scripts/schilderbibliotheek/genereer-migratie.mjs.
-- Niet met de hand bijwerken: pas het script of de mappingtabel aan en draai
-- het opnieuw. Bron: Calc4You Bibliotheek Onderhoud 2025.
--
-- Inhoud: 40 onderdelen, 116 types,
-- 91 behandelingen, 842 combinaties met elk een
-- arbeidsnorm en een materiaalnorm, plus 11 staartkostenrecepten.
--
-- Alles upsert op natuurlijke sleutels; opnieuw draaien is veilig.

-- De spiegel-triggers zouden bij een bulk als deze duizenden keren per rij
-- herbouwen. Ze gaan uit en draaien onderaan één keer over alle combinaties.
alter table public.schilder_combinaties      disable trigger spiegel_combinatie;
alter table public.schilder_arbeid_normen    disable trigger spiegel_arbeid_norm;
alter table public.schilder_materiaal_normen disable trigger spiegel_materiaal_norm;
alter table public.schilder_behandelingen    disable trigger spiegel_behandeling;

