insert into public.schilder_types (onderdeel_id, bron_code, naam, code, eenheid, actief, volgorde)
select o.id, b.bron_code, b.naam, b.bron_code, b.eenheid, true, b.volgorde
  from bron b join public.schilder_onderdelen o on o.code = b.onderdeel_code
on conflict (onderdeel_id, bron_code) do update set
  naam       = excluded.naam,
  eenheid    = excluded.eenheid,
  volgorde   = excluded.volgorde,
  updated_at = now();

-- ── Behandelingen ─────────────────────────────────────────────────────────
-- `korte_omschrijving` is de systeemregel uit Calc4You ("Plaatselijk
-- verwijderen, 1 x bijwerken grondverf, …"); `uitgebreide_werkomschrijving`
-- zijn de werkstappen uit het OnderhoudNL-bestek.
