on conflict (code) do update set
  bron                        = excluded.bron,
  korte_omschrijving          = excluded.korte_omschrijving,
  uitgebreide_werkomschrijving= coalesce(excluded.uitgebreide_werkomschrijving, public.schilder_behandelingen.uitgebreide_werkomschrijving),
  ondergrond                  = excluded.ondergrond,
  toepassing                  = excluded.toepassing,
  volgorde                    = excluded.volgorde,
  updated_at                  = now();

