insert into public.schilder_combinaties (onderdeel_id, type_id, behandeling_id, bron_code, actief)
select o.id, t.id, h.id, b.bron_code, true
  from bron b
  join public.schilder_onderdelen    o on o.code = b.onderdeel_code
  join public.schilder_types         t on t.onderdeel_id = o.id and t.bron_code = b.type_bron_code
  join public.schilder_behandelingen h on h.code = b.behandeling_code
on conflict (bron_code) do update set
  onderdeel_id = excluded.onderdeel_id,
  type_id      = excluded.type_id,
  actief       = true,
  updated_at   = now();

-- ── Arbeids- en materiaalnormen ───────────────────────────────────────────
-- Eerst weg, dan opnieuw: zo blijft de norm gelijk aan de bron, ook als daar
-- iets uit verdwenen is. Alleen normen van combinaties uit déze import.
delete from public.schilder_arbeid_normen a
 using public.schilder_combinaties k
 where a.combinatie_id = k.id and k.bron_code is not null;
delete from public.schilder_materiaal_normen m
 using public.schilder_combinaties k
 where m.combinatie_id = k.id and k.bron_code is not null;

