insert into public.schilder_materiaal_normen
  (combinatie_id, naam, norm_type, quantity_per_unit, eenheid, unit_price, cost_per_unit, actief, volgorde)
select k.id, deel.naam, 'materiaal', 1, b.eenheid, deel.prijs, deel.prijs, true, deel.volgorde
  from bron b
  join public.schilder_combinaties k on k.bron_code = b.bron_code
  cross join lateral (values
    ('Verfmaterialen', round(b.prijs * 0.9, 4), 1),
    ('Non-paints',     b.prijs - round(b.prijs * 0.9, 4), 2)
  ) as deel(naam, prijs, volgorde)
 where b.prijs > 0;

-- ── Spiegel bijwerken ─────────────────────────────────────────────────────
alter table public.schilder_combinaties      enable trigger spiegel_combinatie;
alter table public.schilder_arbeid_normen    enable trigger spiegel_arbeid_norm;
alter table public.schilder_materiaal_normen enable trigger spiegel_materiaal_norm;
alter table public.schilder_behandelingen    enable trigger spiegel_behandeling;

do $spiegel$
declare r record;
begin
  for r in select id from public.schilder_combinaties loop
    perform public.spiegel_schilder_naar_recept(r.id);
  end loop;
end $spiegel$;

-- ── Staartkosten (Bouwplaats / Bereikbaarheid) ────────────────────────────
-- Dit zijn géén genormeerde m²-prijzen maar samengestelde posten, dus ze gaan
-- rechtstreeks naar de recepten-bibliotheek. Ze blijven gewoon bewerkbaar —
-- alleen de gespiegelde schilderrecepten zijn vergrendeld.
insert into public.paint_treatments (family_id, treatment_index_code, treatment_code, name, source, active) values
  ('00000000-0000-0000-0000-000000000001', 'BP', 'BP', 'Bouwplaatsvoorzieningen', 'Calc4You Bibliotheek Onderhoud 2025', true),
  ('00000000-0000-0000-0000-000000000001', 'BB', 'BB', 'Bereikbaarheidsvoorzieningen', 'Calc4You Bibliotheek Onderhoud 2025', true)
on conflict (family_id, treatment_index_code) do update set
  name = excluded.name, source = excluded.source, active = true;

with bron (item_code, treatment_code, onderdeel, volnaam, eenheid) as (values
  ('BP-01', 'BP', 'Bouwplaats', 'Bouwhekken plaatsen, standaard, afmeting 3.500 x 2.000', 'm¹'),
  ('BP-02', 'BP', 'Bouwplaats', 'Schaftwagen met bergruimte', 'week'),
  ('BP-03', 'BP', 'Bouwplaats', 'Bouw- en sloopafval 10 m³', 'st'),
  ('BB-01', 'BB', 'Bereikbaarheid', 'Renovatiesteiger compleet', 'm²'),
  ('BB-02', 'BB', 'Bereikbaarheid', 'Renovatiesteiger bescherming', 'm¹'),
  ('BB-03', 'BB', 'Bereikbaarheid', 'Inzet van hoogwerker', 'week'),
  ('BB-04', 'BB', 'Bereikbaarheid', 'Inzet van rijplaten', 'week'),
  ('BB-05', 'BB', 'Bereikbaarheid', 'Inzet van kraan ten behoeve van aan- & afvoer installatie', 'inzet'),
  ('BB-06', 'BB', 'Bereikbaarheid', 'Inzet van hanginstallatie', 'week'),
  ('BB-07', 'BB', 'Bereikbaarheid', 'Verplaatsingen hangbruginstallatie', 'st'),
  ('BB-08', 'BB', 'Bereikbaarheid', 'Inzet van rolsteiger', 'post')
)
insert into public.paint_items
  (family_id, treatment_id, item_code, onderdeel, type, full_name, default_unit, source, active, btw_tarief)
select '00000000-0000-0000-0000-000000000001', t.id, b.item_code, b.onderdeel, 'voorziening', b.volnaam, b.eenheid, 'Calc4You Bibliotheek Onderhoud 2025', true, 'hoog'
  from bron b
  join public.paint_treatments t on t.family_id = '00000000-0000-0000-0000-000000000001' and t.treatment_index_code = b.treatment_code
on conflict (treatment_id, item_code) do update set
  onderdeel = excluded.onderdeel, full_name = excluded.full_name,
  default_unit = excluded.default_unit, source = excluded.source, active = true;

-- Normen opnieuw opbouwen voor precies deze recepten.
delete from public.paint_labor_norms    where item_id in (select id from public.paint_items where source = 'Calc4You Bibliotheek Onderhoud 2025');
delete from public.paint_material_norms where item_id in (select id from public.paint_items where source = 'Calc4You Bibliotheek Onderhoud 2025');

